#include <iostream>
#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;
const int MAXN = 100010;
const int MAXM = 2000020;
const ll INF = 1000000000LL;

struct Edge {
    int next, to, cap;
    ll cost;
} e[MAXM];

int head[MAXN], ecnt = 1, node_cnt;
vector<int> g[MAXN];

void add_edge(int u, int v, int cap, ll cost) {
    e[++ecnt] = {head[u], v, cap, cost};
    head[u] = ecnt;
    e[++ecnt] = {head[v], u, 0, -cost};
    head[v] = ecnt;
}

namespace MCMF {
    int cur[MAXN];
    bool vis[MAXN];
    ll dist[MAXN], pot[MAXN];

    struct Node {
        int id;
        ll key;
        Node(int i = 0, ll k = 0) : id(i), key(k) {}
        bool operator<(const Node& o) const { return key > o.key; }
    };

    priority_queue<Node> pq;

    bool dijkstra(int s, int t) {
        fill(dist + 1, dist + node_cnt + 1, INF);
        fill(cur + 1, cur + node_cnt + 1, head[1]);
        dist[t] = 0;
        pq.push(Node(t, 0));

        while (!pq.empty()) {
            int u = pq.top().id;
            pq.pop();
            if (vis[u]) continue;
            vis[u] = true;

            for (int i = head[u]; i; i = e[i].next) {
                int v = e[i].to;
                ll w = pot[u] + e[i ^ 1].cost - pot[v];
                if (e[i ^ 1].cap && dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push(Node(v, dist[v]));
                }
            }
        }

        for (int i = 1; i <= node_cnt; ++i)
            pot[i] = min(pot[i] + dist[i], INF);

        if (!vis[s]) return false;
        fill(vis + 1, vis + node_cnt + 1, false);
        return true;
    }

    int dfs(int u, int t, int f) {
        if (u == t || !f) return f;
        int pushed = 0;
        vis[u] = true;

        for (int& i = cur[u]; i; i = e[i].next) {
            if (e[i].cap) {
                int v = e[i].to;
                int flow;
                if (!vis[v] && pot[v] + e[i].cost == pot[u] &&
                    (flow = dfs(v, t, min(f, e[i].cap)))) {
                    e[i].cap -= flow;
                    e[i ^ 1].cap += flow;
                    pushed += flow;
                    f -= flow;
                    if (!f) break;
                }
            }
        }

        vis[u] = false;
        return pushed;
    }

    int total_flow;
    ll total_cost;

    void run(int s, int t) {
        while (dijkstra(s, t)) {
            int flow = dfs(s, t, INF);
            total_flow += flow;
            total_cost += (ll)flow * pot[s];
        }
    }
}

int src = 1, dst = 2, n, m, k, c, d;

inline int idx(int t, int x) { return t * n + x + 2; }

void layer(int t) {
    node_cnt += n;

    for (int u = 1; u <= n; ++u)
        for (int v : g[u])
            for (int p = 1; p <= k; ++p)
                add_edge(idx(t, u), idx(t + 1, v), 1, d * (2 * p - 1));

    for (int u = 1; u <= n; ++u)
        add_edge(idx(t, u), idx(t + 1, u), INF, 0);

    add_edge(idx(t + 1, 1), dst, INF, c * (t + 1));
}

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    node_cnt = n + 2;

    for (int i = 1; i <= k; ++i) {
        int a;
        scanf("%d", &a);
        add_edge(src, idx(0, a), 1, 0);
    }

    for (int i = 1; i <= m; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        g[u].push_back(v);
        g[v].push_back(u);
    }

    add_edge(idx(0, 1), dst, INF, 0);

    for (int i = 0; i <= n + k; ++i)
        layer(i);

    MCMF::run(src, dst);
    printf("%lld\n", MCMF::total_cost);
    return 0;
}
